import { loadFont as loadTxt } from "@remotion/google-fonts/Inter";
import { loadFont as loadHead } from "@remotion/google-fonts/Marcellus";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// NEAFH — Relatório de consultoria ao Hospital Samar, versão 2 (15/10/2026).
// Retorno da v1: "um pouco lento na hora dos motions, use mais imagens inteiras e mande a narração".
// Agora com locução (ElevenLabs "o locutor - Poetic, Soft and Gentle", 96,4 s) e fotos de tela cheia que trocam no ritmo
// das palavras; as de paisagem aparecem inteiras sobre um fundo desfocado da própria foto. Texto curto por cima, parado
// depois de entrar; números de tópico em batidas de fundo liso. Tempos = tempo da palavra na locução (V) + OFF.

const { fontFamily: HEAD } = loadHead("normal", { weights: ["400"], subsets: ["latin", "latin-ext"] });
const { fontFamily: TXT } = loadTxt("normal", { weights: ["500", "600", "700"], subsets: ["latin", "latin-ext"] });

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
export const NR2_FPS = 30;
const OFF = 0.15;
export const NR2_DUR = 98;
export const NR2_FRAMES = NR2_DUR * NR2_FPS;
const NAVY = "#20314D";
const TEAL = "#246E91";
const TEAL_L = "#6FB7D6";
const PAPER = "#F7F9FB";
const INK = "#16233A";

const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.5));
const k = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const rise = (t: number, at: number, dy = 60, d = 0.4): React.CSSProperties => {
  const e = interpolate(t, [at, at + d], [0, 1], { ...cl, easing: BACK });
  return { opacity: interpolate(t, [at, at + 0.15], [0, 1], cl), transform: `translateY(${((1 - e) * dy).toFixed(1)}px)` };
};
const slam = (t: number, at: number, d = 0.22): React.CSSProperties => {
  const e = k(t, at, d);
  return { opacity: t >= at ? Math.min(1, e * 3) : 0, transform: `scale(${(1.6 - 0.6 * e).toFixed(3)})` };
};
const hs = (size: number, color: string): React.CSSProperties => ({ fontFamily: HEAD, fontWeight: 400, fontSize: size, lineHeight: 1.08, color, whiteSpace: "nowrap", letterSpacing: "0.01em" });
const src = (n: number) => staticFile(`neafh/rel/r${String(n).padStart(2, "0")}.jpg`);
const WIDE = [2, 20, 21];                                    // fotos de paisagem: inteiras, sobre fundo desfocado

// ───────── fotos de tela cheia ─────────
type Entry = "punch" | "slide" | "flash" | "pull" | "whip";
type Shot = { a: number; n: number; pos?: string; e: Entry; tint?: "teal" | "dark" | "deep"; lift?: number };
// a = tempo na locução em que a foto entra; fica até a próxima
const SHOTS: Shot[] = [
  { a: 0.0, n: 13, e: "punch", tint: "dark" }, { a: 0.65, n: 10, e: "punch", tint: "dark" }, { a: 1.3, n: 16, e: "punch", tint: "dark", pos: "50% 80%" }, { a: 1.95, n: 9, e: "punch", tint: "dark" },
  { a: 2.7, n: -1, e: "flash" },                            // logo
  { a: 3.8, n: 4, e: "slide", pos: "50% 45%" },
  { a: 5.95, n: 16, e: "pull", tint: "deep", pos: "50% 70%" }, { a: 8.6, n: 4, e: "punch", tint: "deep" }, { a: 10.58, n: 15, e: "pull", tint: "deep" },
  { a: 12.6, n: 7, e: "whip" }, { a: 15.3, n: 18, e: "punch" },
  { a: 17.35, n: 13, e: "slide", pos: "50% 65%" }, { a: 18.85, n: 14, e: "whip", pos: "50% 70%" },
  { a: 20.45, n: -2, e: "flash" },                          // impactos (liso)
  { a: 23.3, n: -3, e: "slide" },                           // plano de contingência (liso)
  { a: 28.6, n: -4, e: "punch" },                           // 01
  { a: 30.55, n: 3, e: "whip" }, { a: 32.45, n: 1, e: "pull", pos: "50% 55%" }, { a: 35.5, n: 22, e: "slide", lift: 300 },
  { a: 38.4, n: -4, e: "flash" },                           // 02
  { a: 41.6, n: 10, e: "punch" }, { a: 42.9, n: 11, e: "whip" }, { a: 43.65, n: 12, e: "punch" }, { a: 44.35, n: 5, e: "slide" }, { a: 45.05, n: 15, e: "whip" }, { a: 45.65, n: 9, e: "punch" }, { a: 46.9, n: 8, e: "slide" },
  { a: 47.95, n: -5, e: "punch" },                          // 03 · 70
  { a: 50.75, n: 20, e: "slide" }, { a: 52.9, n: 19, e: "whip", pos: "50% 60%" },
  { a: 56.3, n: -4, e: "flash" },                           // 04
  { a: 58.95, n: 17, e: "punch", lift: 300 }, { a: 61.55, n: 12, e: "pull" }, { a: 64.5, n: 14, e: "whip", pos: "50% 70%" }, { a: 66.45, n: 13, e: "punch", pos: "50% 65%" }, { a: 68.85, n: 2, e: "slide" }, { a: 70.85, n: 7, e: "whip" }, { a: 72.65, n: 21, e: "pull" },
  { a: 75.1, n: 6, e: "whip" }, { a: 77.9, n: 18, e: "punch" },
  { a: 81.4, n: 23, e: "flash", tint: "teal", pos: "50% 55%" },
  { a: 85.1, n: 4, e: "slide", pos: "50% 45%" }, { a: 87.55, n: 20, e: "whip" }, { a: 89.95, n: 21, e: "punch" },
  { a: 92.7, n: -6, e: "flash" },                           // assinatura
];

const Pic: React.FC<{ n: number; t: number; a: number; b: number; pos?: string; lift?: number }> = ({ n, t, a, b, pos = "50% 50%", lift = 0 }) => {
  const z = 1.04 + 0.1 * lin(t, a, b + 0.4);
  if (WIDE.includes(n)) {
    return (
      <AbsoluteFill>
        <Img src={src(n)} style={{ position: "absolute", inset: -60, width: 1200, height: 2040, objectFit: "cover", filter: "blur(40px) brightness(0.55)" }} />
        <Img src={src(n)} style={{ position: "absolute", left: 0, top: 960 - 243 - 260, width: 1080, height: 486, objectFit: "cover", transform: `scale(${z.toFixed(4)})` }} />
      </AbsoluteFill>
    );
  }
  return <Img src={src(n)} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", objectPosition: pos, transform: `translateY(${-lift}px) scale(${z.toFixed(4)})`, ...(lift ? { WebkitMaskImage: "linear-gradient(180deg, #000 70%, transparent 88%)" } : {}) }} />;
};

const Plain: React.FC<{ bg: string; t: number; a: number; b: number; children: React.ReactNode }> = ({ bg, t, a, b, children }) => (
  <AbsoluteFill style={{ background: bg }}>
    <AbsoluteFill style={{ transform: `scale(${(0.94 + 0.08 * lin(t, a, b)).toFixed(4)})` }}>{children}</AbsoluteFill>
  </AbsoluteFill>
);

const col = (top: number, gap = 10): React.CSSProperties => ({ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", gap });
const Kicker: React.FC<{ t: number; at: number; c?: string; children: string }> = ({ t, at, c = TEAL_L, children }) => (
  <div style={{ display: "flex", alignItems: "center", gap: 18, ...rise(t, at, 24) }}>
    <div style={{ width: 48 * k(t, at, 0.5), height: 4, background: c }} />
    <div style={{ fontFamily: TXT, fontWeight: 700, fontSize: 30, letterSpacing: "0.22em", color: c, textTransform: "uppercase", whiteSpace: "nowrap" }}>{children}</div>
    <div style={{ width: 48 * k(t, at, 0.5), height: 4, background: c }} />
  </div>
);
const Words: React.FC<{ t: number; at: number; text: string; size: number; color?: string; hl?: string[]; hlc?: string; step?: number }> = ({ t, at, text, size, color = "#FFFFFF", hl = [], hlc = TEAL_L, step = 0.05 }) => (
  <div style={{ width: 840, display: "flex", flexWrap: "wrap", justifyContent: "center", columnGap: size * 0.26, rowGap: size * 0.08 }}>
    {text.split(" ").map((w, i) => (
      <span key={i} style={{ ...hs(size, hl.includes(w) ? hlc : color), display: "inline-block", textShadow: color === "#FFFFFF" ? "0 4px 24px rgba(10,20,40,0.45)" : undefined, ...rise(t, at + i * step, size * 0.45) }}>{w}</span>
    ))}
  </div>
);
const Check: React.FC<{ s: number }> = ({ s }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke="#FFFFFF" strokeWidth={3.2} strokeLinecap="round" strokeLinejoin="round"><path d="M4.5 12.5l5 5L19.5 7" /></svg>
);
const Badge: React.FC<{ t: number; at: number }> = ({ t, at }) => (
  <div style={{ width: 70, height: 70, borderRadius: 35, background: TEAL, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${pop(t, at, 0.4).toFixed(3)})` }}><Check s={40} /></div>
);

// ───────── texto por cima das fotos: uma frase por vez, no mesmo lugar ─────────
type Cap = { a: number; b: number; kick?: string; head: string; size?: number; hl?: string[]; check?: boolean; sub?: string; subAt?: number };
const CAPS: Cap[] = [
  { a: 3.85, b: 5.95, kick: "Relatório de consultoria", head: "À Diretoria do Hospital Samar", size: 80, hl: ["Samar"] },
  { a: 12.75, b: 15.3, kick: "Julho deste ano", head: "Assumimos o compromisso", size: 80 },
  { a: 15.35, b: 17.3, head: "Reverter um cenário crítico", size: 88, hl: ["crítico"] },
  { a: 17.45, b: 18.85, head: "Prontuários represados", size: 92, hl: ["represados"] },
  { a: 18.95, b: 20.4, head: "Atrasos no faturamento", size: 92, hl: ["Atrasos"] },
  { a: 30.6, b: 32.4, kick: "01 · Força-tarefa", head: "Auditoria e faturamento", size: 84, hl: ["faturamento"] },
  { a: 32.5, b: 35.45, head: "Unificados numa operação conjunta", size: 80, hl: ["conjunta"] },
  { a: 35.55, b: 38.3, head: "Contas liberadas mais rápido para os convênios", size: 72, hl: ["convênios"], check: true },
  { a: 41.7, b: 44.3, kick: "02 · Capacitação", head: "Diversos treinamentos com as equipes", size: 76, hl: ["treinamentos"] },
  { a: 44.4, b: 45.6, head: "Gargalos mapeados", size: 92, hl: ["Gargalos"] },
  { a: 45.7, b: 47.85, head: "Soluções práticas e imediatas", size: 84, hl: ["práticas", "imediatas"] },
  { a: 50.8, b: 52.85, head: "Parte expressiva já concluída", size: 84, hl: ["concluída"], check: true },
  { a: 52.95, b: 56.2, head: "Os demais prontos para as equipes internas", size: 76, hl: ["prontos"] },
  { a: 59.05, b: 61.5, kick: "04 · Transição de conhecimento", head: "Auditoria no faturamento in loco", size: 76, hl: ["in loco"], check: true },
  { a: 61.6, b: 64.4, head: "Em todas as pontas do hospital", size: 80, sub: "há 50 dias", subAt: 63.2 },
  { a: 64.6, b: 68.75, head: "Contas antigas represadas faturadas e enviadas", size: 76, hl: ["faturadas", "enviadas"], check: true },
  { a: 68.95, b: 72.6, head: "Precificação de taxas e diárias", size: 84, hl: ["taxas", "diárias"], check: true },
  { a: 72.75, b: 75.0, head: "Entendimento lógico da dieta enteral", size: 80, hl: ["dieta", "enteral"], check: true },
  { a: 75.2, b: 77.85, kick: "05 · Por fim", head: "Diretrizes estruturadas", size: 88, hl: ["Diretrizes"] },
  { a: 77.95, b: 81.3, head: "Para os colaboradores do Samar darem continuidade", size: 72, hl: ["continuidade"] },
  { a: 81.5, b: 85.0, head: "As bases para uma gestão eficiente estão solidificadas", size: 80, hl: [] },
  { a: 85.2, b: 87.5, kick: "Agradecemos à diretoria", head: "Pelo compromisso", size: 88, hl: ["compromisso"] },
  { a: 87.6, b: 89.9, head: "Pela transparência", size: 92, hl: ["transparência"] },
  { a: 89.95, b: 92.6, head: "E pela confiança", size: 92, hl: ["confiança"], sub: "À disposição para as próximas etapas", subAt: 90.15 },
];

// números de tópico (fundo liso)
const NUMS: [number, number, string, string][] = [[28.6, 30.55, "01", "Força-tarefa"], [38.4, 41.6, "02", "Capacitação e diagnóstico"], [56.3, 58.95, "04", "Transição de conhecimento"]];

export const NeafhRelatorio2: React.FC = () => {
  const tt = useCurrentFrame() / NR2_FPS;
  const t = tt - OFF;                                         // tempo da locução
  const i = Math.max(0, SHOTS.findIndex((s, j) => t >= s.a && (j + 1 >= SHOTS.length || t < SHOTS[j + 1].a)));
  const s = SHOTS[i];
  const b = i + 1 < SHOTS.length ? SHOTS[i + 1].a : NR2_DUR;
  const e = k(t, s.a, 0.32);
  const prev = i > 0 ? SHOTS[i - 1] : undefined;
  // entrada de cada foto
  let wrap: React.CSSProperties = {};
  if (s.e === "punch") wrap = { transform: `scale(${(1 + 0.18 * (1 - e)).toFixed(4)})` };
  if (s.e === "pull") wrap = { transform: `scale(${(1.25 - 0.25 * e).toFixed(4)})` };
  if (s.e === "slide") wrap = { transform: `translateX(${((1 - e) * 1080 * (i % 2 ? -1 : 1)).toFixed(0)}px)` };
  if (s.e === "whip") wrap = { transform: `translateY(${((1 - e) * 1920 * (i % 2 ? 1 : -1)).toFixed(0)}px)`, filter: `blur(${((1 - e) * 24).toFixed(1)}px)` };
  const flash = s.e === "flash" ? 1 - lin(t, s.a, s.a + 0.25) : 0;

  const shot = (x: Shot, a: number, bb: number) => {
    if (x.n > 0) {
      return (
        <AbsoluteFill>
          <Pic n={x.n} t={t} a={a} b={bb} pos={x.pos} lift={x.lift} />
          {x.tint === "dark" && <AbsoluteFill style={{ background: NAVY, opacity: 0.55 }} />}
          {x.tint === "deep" && <AbsoluteFill style={{ background: NAVY, opacity: 0.82 }} />}
          {x.tint === "teal" && <AbsoluteFill style={{ background: TEAL, opacity: 0.72 }} />}
        </AbsoluteFill>
      );
    }
    if (x.n === -1) return <Plain bg={PAPER} t={t} a={a} b={bb}><div style={{ ...col(760, 0) }}><Img src={staticFile("neafh/logo.png")} style={{ width: 600, ...rise(t, a + 0.05, 80) }} /></div></Plain>;
    if (x.n === -2) return (
      <Plain bg={TEAL} t={t} a={a} b={bb}>
        <div style={{ ...col(700, 20) }}>
          <div style={{ ...hs(120, "#FFFFFF"), ...slam(t, 20.55) }}>Impactos</div>
          <div style={{ ...hs(96, "#FFFFFF"), ...slam(t, 21.15) }}>financeiros</div>
          <div style={{ ...hs(96, "#D5E8F1"), ...slam(t, 21.7) }}>negativos</div>
        </div>
      </Plain>
    );
    if (x.n === -3) return (
      <Plain bg={NAVY} t={t} a={a} b={bb}>
        <div style={{ ...col(660, 34) }}>
          <Kicker t={t} at={23.5}>Imediatamente</Kicker>
          <Words t={t} at={24.5} text="Plano de contingência" size={110} step={0.12} hl={["contingência"]} />
          <div style={{ fontFamily: TXT, fontWeight: 600, fontSize: 46, color: "#C3CFDF", textAlign: "center", ...rise(t, 26.9, 30) }}>focado em eficiência operacional</div>
        </div>
      </Plain>
    );
    if (x.n === -4) {
      const [, , num, name] = NUMS.find(([na]) => Math.abs(na - a) < 0.01)!;
      return (
        <Plain bg={num === "02" ? TEAL : NAVY} t={t} a={a} b={bb}>
          <div style={{ ...col(560, 10) }}>
            <div style={{ ...hs(420, num === "02" ? "#FFFFFF" : TEAL_L), lineHeight: 1, ...slam(t, a + 0.08, 0.26) }}>{num}</div>
            <div style={{ marginTop: 30 }}><Words t={t} at={a + 0.5} text={name} size={80} /></div>
          </div>
        </Plain>
      );
    }
    if (x.n === -5) return (
      <Plain bg={PAPER} t={t} a={a} b={bb}>
        <div style={{ ...col(560, 0) }}>
          <Kicker t={t} at={a + 0.1} c={TEAL}>03 · Planos de ação</Kicker>
          <div style={{ ...hs(400, TEAL), lineHeight: 1, marginTop: 40, ...rise(t, 48.95, 80) }}>{Math.round(70 * interpolate(t, [48.95, 49.7], [0, 1], { ...cl, easing: OUT }))}</div>
          <div style={{ ...hs(80, INK), marginTop: 20, ...rise(t, 49.7, 40) }}>planos de ação</div>
        </div>
      </Plain>
    );
    // assinatura
    return (
      <Plain bg={PAPER} t={t} a={a} b={bb}>
        <div style={{ ...col(600, 0) }}>
          <div style={{ fontFamily: TXT, fontWeight: 500, fontSize: 38, color: "#6B7A90", ...rise(t, a + 0.1, 30) }}>Atenciosamente,</div>
          <Img src={staticFile("neafh/logo.png")} style={{ width: 600, marginTop: 50, ...rise(t, a + 0.2, 70) }} />
        </div>
        <div style={{ ...col(1220, 0) }}><Words t={t} at={92.9} text="Núcleo de Evidências em Auditoria · Faturamento Hospitalar" size={56} color={INK} step={0.12} /></div>
      </Plain>
    );
  };

  const cap = CAPS.find((c) => t >= c.a && t < c.b + 0.2);
  const capO = cap ? 1 - lin(t, cap.b, cap.b + 0.18) : 0;
  const onPhoto = s.n > 0;
  return (
    <AbsoluteFill style={{ background: NAVY, overflow: "hidden" }}>
      {/* a foto anterior fica embaixo enquanto a nova entra deslizando */}
      {prev && (s.e === "slide" || s.e === "whip") && t < s.a + 0.32 && <AbsoluteFill>{shot(prev, prev.a, s.a + 0.32)}</AbsoluteFill>}
      <AbsoluteFill style={wrap}>{shot(s, s.a, b)}</AbsoluteFill>
      {onPhoto && cap && <AbsoluteFill style={{ background: `linear-gradient(180deg, rgba(32,49,77,0) 45%, rgba(32,49,77,0.88) 72%, rgba(32,49,77,0.96) 100%)`, opacity: Math.min(1, lin(t, cap.a - 0.15, cap.a + 0.1)) }} />}

      {/* abertura em batidas */}
      {t < 2.7 && (
        <div style={{ ...col(820, 6) }}>
          {t < 0.65 && <div style={{ ...hs(130, "#FFFFFF"), ...slam(t, 0.05) }}>RELATÓRIO</div>}
          {t >= 0.65 && t < 1.3 && <><div style={{ ...hs(64, TEAL_L), ...slam(t, 0.65) }}>DE</div><div style={{ ...hs(104, "#FFFFFF"), ...slam(t, 0.7) }}>CONSULTORIA</div></>}
          {t >= 1.3 && t < 1.95 && <div style={{ ...hs(116, "#FFFFFF"), ...slam(t, 1.35) }}>HOSPITALAR</div>}
          {t >= 1.95 && <div style={{ ...hs(92, "#FFFFFF"), ...slam(t, 1.99) }}>ESPECIALIZADA</div>}
        </div>
      )}

      {/* diretores */}
      {t >= 5.95 && t < 12.6 && (
        <div style={{ ...col(560, 0) }}>
          <Kicker t={t} at={6.0}>Prezados diretores</Kicker>
          {([["Dra. Ana Cláudia", "Diretora Médica", 6.14], ["Fernando Carlos", "CEO", 8.64], ["Nicaele", "Controladoria", 10.62]] as const).map(([n, r, at]) => (
            <div key={n} style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6, marginTop: 70, ...rise(t, at, 50) }}>
              <div style={{ ...hs(84, "#FFFFFF"), textShadow: "0 4px 24px rgba(10,20,40,0.5)" }}>{n}</div>
              <div style={{ fontFamily: TXT, fontWeight: 700, fontSize: 34, letterSpacing: "0.18em", color: TEAL_L, textTransform: "uppercase" }}>{r}</div>
            </div>
          ))}
        </div>
      )}

      {/* frase da vez */}
      {cap && (
        <div style={{ ...col(s.n === 23 ? 1180 : 1330, 22), opacity: capO }}>
          {cap.check && <Badge t={t} at={cap.a} />}
          {cap.kick && <Kicker t={t} at={cap.a}>{cap.kick}</Kicker>}
          <Words t={t} at={cap.a + 0.08} text={cap.head} size={cap.size ?? 80} hl={cap.hl} />
          {cap.sub && <div style={{ fontFamily: TXT, fontWeight: 700, fontSize: 44, color: TEAL_L, textAlign: "center", textTransform: cap.sub.startsWith("há") ? "uppercase" : undefined, letterSpacing: cap.sub.startsWith("há") ? "0.12em" : undefined, ...rise(t, cap.subAt ?? cap.a + 0.6, 30) }}>{cap.sub}</div>}
        </div>
      )}

      {flash > 0 && <AbsoluteFill style={{ background: "#FFFFFF", opacity: flash * 0.85 }} />}
    </AbsoluteFill>
  );
};

import React from "react";
import { Composition, registerRoot } from "remotion";
import { NR2_FPS, NR2_FRAMES, NeafhRelatorio2 } from "./NeafhRelatorio2";

const Root: React.FC = () => (
  <>
    <Composition id="NeafhRelatorio2" component={NeafhRelatorio2} durationInFrames={NR2_FRAMES} fps={NR2_FPS} width={1080} height={1920} />
  </>
);
registerRoot(Root);
